// Editable image-space articulated puppet; this is not automatic anatomy recovery.
export const cutoutWalkDefaults={walkRate:.85,walkStride:12,walkKnee:10,walkPhase:0,walkBob:3,walkEdgeThreshold:100,walkRig:{width:1024,height:1536,hip:[520,930],backKnee:[310,1160],frontKnee:[700,1170],flashlight:[850,690],parts:{body:[[0,0],[1024,0],[1024,960],[0,960]],backThigh:[[350,890],[550,940],[390,1195],[220,1160]],backShin:[[235,1120],[405,1160],[370,1475],[45,1475],[45,1320]],frontThigh:[[500,890],[740,900],[810,1200],[600,1210]],frontShin:[[600,1130],[805,1120],[860,1290],[980,1370],[965,1490],[620,1490]]}}};
const cache=new WeakMap();function parts(image,f){const key=JSON.stringify([f.walkRig,f.walkEdgeThreshold,image.src,image._assetRevision]),old=cache.get(image);if(old?.key===key)return old.parts;const rig=f.walkRig,result={};for(const [name,poly]of Object.entries(rig.parts)){const canvas=Object.assign(document.createElement('canvas'),{width:rig.width,height:rig.height}),c=canvas.getContext('2d');c.beginPath();poly.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.closePath();c.clip();c.drawImage(image,0,0,rig.width,rig.height);const pixels=c.getImageData(0,0,rig.width,rig.height);for(let i=3;i<pixels.data.length;i+=4)if(pixels.data[i]<f.walkEdgeThreshold)pixels.data[i]=0;c.putImageData(pixels,0,0);result[name]=canvas}cache.set(image,{key,parts:result});return result;}
export function cutoutWalkPose(time,input={}){const f={...cutoutWalkDefaults,...input},p=time*f.walkRate*Math.PI*2+f.walkPhase;return {back:Math.sin(p)*f.walkStride,front:-Math.sin(p)*f.walkStride,backKnee:Math.max(0,Math.sin(p+.7))*f.walkKnee,frontKnee:Math.max(0,-Math.sin(p+.7))*f.walkKnee,bob:Math.cos(p*2)*f.walkBob};}
export function paintCutoutWalk(c,image,time,rect,input={}){if(!(image?.naturalWidth||image?.width))return false;const f={...cutoutWalkDefaults,...input},rig=f.walkRig,ps=parts(image,f),pose=cutoutWalkPose(time,f),[x,y,w,h]=rect;c.save();c.translate(x,y+pose.bob*h/rig.height);c.scale(w/rig.width,h/rig.height);const hip=rig.hip,draw=(name,origin)=>c.drawImage(ps[name],-origin[0],-origin[1]);for(const side of ['back','front']){c.save();c.translate(...hip);c.rotate(pose[side]*Math.PI/180);draw(side+'Thigh',hip);const knee=rig[side+'Knee'];c.translate(knee[0]-hip[0],knee[1]-hip[1]);c.rotate(pose[side+'Knee']*Math.PI/180);draw(side+'Shin',knee);c.restore();}c.drawImage(ps.body,0,0);c.restore();return {flashlight:[x+rig.flashlight[0]/rig.width*w,y+rig.flashlight[1]/rig.height*h],pose};}
